    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self._components = n
        self._history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)

        if ra == rb:
            return False

        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra

        self._history.append((rb, ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self._components -= 1
        return True

    def snapshot(self):
        return len(self._history)

    def rollback(self, token):
        while len(self._history) > token:
            rb, ra, old_size_ra = self._history.pop()
            self.parent[rb] = rb
            self.size[ra] = old_size_ra
            self._components += 1

