def transfer_all(accounts, ops):
    n = len(accounts)
    locks = [threading.Lock() for _ in range(n)]

    def worker(src, dst, amount):
        if not (0 <= src < n and 0 <= dst < n):
            return

        if src == dst:
            with locks[src]:
                return

        if src < dst:
            first, second = src, dst
        else:
            first, second = dst, src

        with locks[first]:
            with locks[second]:
                if amount > 0 and accounts[src] >= amount:
                    accounts[src] -= amount
                    accounts[dst] += amount

    threads = []
    for src, dst, amount in ops:
        t = threading.Thread(target=worker, args=(src, dst, amount))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return accounts

