function pLimit(n) {
  let active = 0;
  const queue = [];

  const next = () => {
    while (active < n && queue.length > 0) {
      active += 1;
      const { fn, resolve, reject } = queue.shift();

      let promise;
      try {
        promise = fn();
      } catch (error) {
        active -= 1;
        reject(error);
        continue;
      }

      Promise.resolve(promise).then(
        (value) => {
          active -= 1;
          resolve(value);
          next();
        },
        (reason) => {
          active -= 1;
          reject(reason);
          next();
        }
      );
    }
  };

  return (fn) =>
    new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
}

module.exports = pLimit;

